// Sanitize Data: builds the Brave query input and the two Perplexity research briefs from the founder's answers.
const d = $('Prepare Client Data').first().json;
const clean = (v) => (v === undefined || v === null) ? '' : String(v).replace(/\s+/g, ' ').trim();
const orNA = (v) => clean(v) || 'NOT PROVIDED';
// RUN DATE: the date this run started, read from the workflow clock. It is never hardcoded and never left to a
// model's own sense of the current year. Every prompt that judges a date is given this line.
const runDate = (() => {
  let ms = Date.now();
  try { const c = $('Founder Context').first().json; if (c && Number(c.run_started_ms) > 0) ms = Number(c.run_started_ms); } catch (e) {}
  const d = new Date(ms);
  const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const iso = d.toISOString().slice(0, 10);
  return { ms, iso, line: 'RUN DATE: today is ' + iso + ' (' + d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()] + ' ' + d.getUTCFullYear() + '), timezone UTC. This is the current date. Do not rely on your own sense of the current year. A date on or before ' + iso + ' is in the past and is not an error. Only a date after ' + iso + ' is in the future; a future publication date is an error to report and is never treated as published.' };
})();

const research_system = 'You are a research assistant collecting evidence for a business plan. Report only what your sources state. Do not give advice, opinions, estimates, or conclusions. Do not calculate averages or ranges yourself. Never invent a source, figure, name, or date. ' + runDate.line;

const business = [
  'BUSINESS BEING RESEARCHED (the founder\'s own description, not verified)',
  'Idea: ' + orNA(d.business_idea),
  'Problem it solves: ' + orNA(d.additional_notes),
  'Target customer: ' + orNA(d.target_customer),
  'Industry: ' + orNA(d.industry),
  'Location: ' + orNA(d.location),
  'Revenue model: ' + orNA(d.revenue_model),
  'Stated differentiator: ' + orNA(d.differentiator),
].join('\n');

// The URL field is what ties a claim to its source. Build Evidence matches it against the pages the search returned.
// The marker [n] is kept only as a fallback, because markers are not always numbered in the order of the returned pages.
const format = [
  'Answer the questions below. Under each question heading, write one claim per line in exactly this format:',
  'CLAIM: <one factual statement, including its scope, geography, currency, and year where relevant> | SOURCE TYPE: <government, regulator, statistics office, company own website, company filing, academic, research firm, industry organization, news publication, vendor blog, listicle or directory, community or forum> | PUBLISHED: <date shown on the source, or date not shown> | URL: <the full address of the one page that states this claim, copied exactly from your search results> [n]',
  'Every CLAIM line must carry the URL of the page that states it. A claim with no URL, or with a URL that is not one of your search results, is discarded.',
  'One claim, one page. If two pages state the same thing, write two CLAIM lines.',
  'A claim about a company must start with that company\'s name, and its URL must be a page on that company\'s own website unless the SOURCE TYPE says otherwise.',
  'Copy prices exactly as the page shows them, with the currency, and say what the price buys. Do not join two prices into a range unless the page states the range.',
  'End every CLAIM line with the citation marker of the same page.',
  'Try at least three different search angles for each question before giving up. Only then write one line: NOT FOUND: <what you looked for>.',
].join('\n');

const rules = [
  'RULES',
  '- Prefer sources from the 24 months before the RUN DATE for prices, features, rules, and market figures. Always give the date shown on the source, exactly as shown. Never report a date later than the RUN DATE.',
  '- Prefer primary and authoritative sources: government data, statistics offices, regulators, company websites, industry organizations, established research firms. Use list articles and vendor blogs only when nothing better exists, and label them honestly.',
  '- Do not write typically, on average, industry standard, research shows, or similar unless a specific cited source states it.',
  '- Do not say that no competitors exist or that a market is underserved. Report only what you found.',
  '- A search result summary is not a source. Cite only pages whose content states the claim.',
].join('\n');

const research_prompt = [
  business, '', format, '',
  '## C1 Direct competitors',
  'Find 4 to 8 businesses selling a similar solution to the same target customer, in or serving the stated location. Prefer each company\'s own website over review sites, directories, and list articles. For each business write separate CLAIM lines, each starting with the business name, for: who its customer is; what it sells; its price, only if published on its own website; how it positions itself; and anything its own website says the offer does not include. Skip any of these you cannot find. Do not guess.',
  '',
  '## C2 Indirect competitors and substitutes',
  'Different paid solutions this customer uses for the same problem, and the free or do-it-yourself ways they solve it (communities, free content, existing advisors). Name specific examples and what each offers. Start each CLAIM line with the name of the business or site it is about.',
  '', rules,
].join('\n');

const market_prompt = [
  business, '', format, '',
  '## M1 Market size and growth',
  'Market size or growth figures for this exact niche, from government sources, statistics offices, company filings, academic work, industry organizations, or established research firms. State exactly what each figure measures, its geography, and its year. If no figure exists for the exact niche, report figures for the closest adjacent markets or customer groups instead, and begin each of those claims with the word ADJACENT followed by a colon and what the figure measures.',
  '',
  '## M2 Customer group and trends',
  'How many people are in the target customer group and how that is changing: demographic statistics, adoption trends, relevant surveys.',
  '',
  '## M3 Evidence that customers pay',
  'Evidence that this customer has this problem and pays to solve it: surveys, consumer spending data, published prices people pay for comparable solutions, search behavior, recurring complaints. Forums, Reddit, and social media are SOURCE TYPE community or forum; they show sentiment only.',
  '',
  '## M4 Where these customers look for help',
  'Evidence about which channels, platforms, or communities this customer group uses to find solutions like this one: platform usage surveys for this group, search behavior, community sizes. Report what sources state. Do not infer from age or demographic stereotypes.',
  '',
  '## M5 Rules and costs',
  'Licensing, registration, tax, or regulatory requirements, and platform or payment fees, that apply to this business in this location, from official or provider sources.',
  '', rules,
].join('\n');

return {
  run_date: runDate.iso,
  query: [d.business_idea, d.target_customer, d.industry, d.location].map(clean).filter(Boolean).join(' | '),
  research_system,
  research_prompt,
  market_prompt,
};

// Build Growth Payload: assembles the Growth writer request from the founder context, the computed financial model, and the evidence.
// The writer sees only verified evidence: the ledger, the sources that have a verified claim, and the research gaps.
// Search listings are not passed. A page found by search reaches the writer only as a verified ledger entry.
const ctx = $('Founder Context').first().json;
const ev = $('Build Evidence').first().json;
const fin = $('Compute Financials').first().json;
const sources = JSON.parse(ev.sources || '[]');
// RUN DATE: the date this run started, read from the workflow clock. It is never hardcoded and never left to a
// model's own sense of the current year. Every prompt that judges a date is given this line.
const runDate = (() => {
  let ms = Date.now();
  try { const c = $('Founder Context').first().json; if (c && Number(c.run_started_ms) > 0) ms = Number(c.run_started_ms); } catch (e) {}
  const d = new Date(ms);
  const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const iso = d.toISOString().slice(0, 10);
  return { ms, iso, line: 'RUN DATE: today is ' + iso + ' (' + d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()] + ' ' + d.getUTCFullYear() + '), timezone UTC. This is the current date. Do not rely on your own sense of the current year. A date on or before ' + iso + ' is in the past and is not an error. Only a date after ' + iso + ' is in the future; a future publication date is an error to report and is never treated as published.' };
})();
let ledger = [];
try { const p = JSON.parse(ev.research_ledger); if (Array.isArray(p)) ledger = p; } catch (e) {}
const verified = new Set(ledger.flatMap((c) => c.source_ids || []));

const user = [
  runDate.line,
  '',
  'GOAL BRIEF',
  fin.goal_brief,
  '',
  fin.financial_model,
  '',
  'SOURCES (only pages on which at least one claim was verified; no other page may be cited)',
  JSON.stringify(sources.filter((s) => verified.has(s.id)).map(({ id, kind, title, domain, published }) => ({ id, kind, title, domain, published })), null, 1),
  '',
  'EVIDENCE LEDGER (each entry was verified against the text of its page; page_excerpt is the supporting passage)',
  ev.research_ledger,
  '',
  'RESEARCH GAPS',
  ev.research_gaps || 'None recorded.',
  '',
  'HOW TO USE THE EVIDENCE',
  '- A verified source is not a verified claim. Cite a source ID only for what one ledger entry states. Do not add detail about a company or page that its ledger entries do not state.',
  '- A conclusion you draw from the evidence is IdeaToPlan\'s inference. Word it as an inference and give it no source ID.',
  '- Competitors existing shows that competing offers exist. It is not evidence of buyers, sales, or willingness to pay. State demand as confirmed only when a ledger entry reports customers paying, spending, survey, or search-behavior evidence, and cite that entry. Otherwise state demand as a hypothesis that requires validation.',
  '- The offer\'s own price is a planning assumption. Label it as one and give it no source ID. A page that states no price cannot support, inform, or benchmark a price: cite such pages only for the service descriptions they support. Never say the price is validated by the market.',
  '- A competitor price in the ledger is the price of that competitor\'s own offer. Give its amount, currency, what it buys, its length, and any qualifier exactly as the ledger entry states them. Keep separate offers separate. Call it an adjacent reference point; never call it equivalent to this offer.',
  '- Say that a provider is paid, charges, or sells only when a ledger entry for that provider states a price, a fee, or a charge. This holds with or without a source ID, and in every section: "paid relocation services" in a list of alternatives needs it too. An entry marked payment_not_established does not support it. Otherwise describe what they offer.',
  '- Do not assign providers a focus, a stage, or a kind of customer that their ledger entries do not state. The entries list services. They do not say that a provider works only after a decision is made, focuses on logistics or execution, or leaves the planning stage out. Say what the pages list and stop there.',
  '- A survey finding is what the survey asked, of whom, and how many. Keep all three every time you use it ("nearly two-thirds of 600 surveyed travelers said ..."). Never write that it confirms, proves, or shows that something is true of travelers, customers, or people in general, or of this customer.',
  '- A superlative needs comparative evidence. "The most common substitute", "the biggest barrier", "the most popular channel" compare one thing with all the others. Without a ledger entry that makes that comparison, say that it is one substitute, barrier, or channel, and that how it compares with the others is not established.',
  '- A market existing means offers are available. It is not demonstrated demand. Say that competing offers exist.',
  '- One company\'s page supports statements about that company only. Do not generalize it to competitors, and do not add audiences, track records, or reputation that the ledger entry does not state.',
  '- W IDs are pages found by web search. They appear in the ledger only when verified and are used exactly like S IDs. Search listings themselves are not evidence and are not provided.',
  '- Judge source dates against the RUN DATE. Never call a date on or before the RUN DATE anomalous or future-dated.',
].join('\n');

return {
  payload: JSON.stringify({ model: 'anthropic/claude-sonnet-4.6', max_tokens: 20000, temperature: 0.3, messages: [{ role: 'system', content: ctx.writer_system }, { role: 'user', content: user }] }),
};

const fp = $('Finalize Plan').first().json;
let plan = fp.text || '';
const data = $('Prepare Client Data').first().json;
let sources = [];
if (Array.isArray(fp.sources_cited)) sources = fp.sources_cited;
plan = plan.replace(/\s*\u2014\s*/g, ' - ').replace(/\u2014/g, '-');
// A line of dashes is a section break in the writer's text. Sections already have headings, so the mark is dropped
// instead of being printed. A rule number in a heading is dropped too, should one reach this point.
plan = plan.replace(/^\s*-{3,}\s*$/gm, '').replace(/\n{3,}/g, '\n\n').replace(/^(\s*(?:#{1,6}\s+|\*\*)?)Rule \d+[:.]\s*/gim, '$1');
const properName = (data.client_name || '').trim().replace(/\b\w/g, c => c.toUpperCase());
const esc = (v) => String(v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const convertTables = (src) => {
  const lines = src.split('\n');
  const out = [];
  let i = 0;
  while (i < lines.length) {
    if (/^\s*\|.*\|\s*$/.test(lines[i])) {
      const block = [];
      while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) { block.push(lines[i]); i++; }
      const rows = block
        .map(l => l.trim().replace(/^\||\|$/g, '').split('|').map(c => c.trim()))
        .filter(cells => !cells.every(c => /^:?-{2,}:?$/.test(c) || c === ''));
      if (rows.length) {
        let t = '<table><thead><tr>' + rows[0].map(c => '<th>' + c + '</th>').join('') + '</tr></thead><tbody>';
        for (let r = 1; r < rows.length; r++) { t += '<tr>' + rows[r].map(c => '<td>' + c + '</td>').join('') + '</tr>'; }
        t += '</tbody></table>';
        out.push(t);
      }
    } else { out.push(lines[i]); i++; }
  }
  return out.join('\n');
};
const CALLOUT_LABELS = { 'RECOMMENDS': 'IdeaToPlan recommends', 'DO THIS FIRST': 'Do this first', 'BIGGEST RISK': 'Biggest risk', 'VALIDATE THIS': 'Validate this', 'FIRST REVENUE MILESTONE': 'First revenue milestone', 'WATCH THIS NUMBER': 'Watch this number' };
const formatPlan = (text) => {
  return convertTables(text)
    .replace(/^>>\s*(RECOMMENDS|DO THIS FIRST|BIGGEST RISK|VALIDATE THIS|FIRST REVENUE MILESTONE|WATCH THIS NUMBER):\s*(.+)$/gm, (m, k, v) => '<div class="callout' + (k === 'BIGGEST RISK' ? ' risk' : '') + '"><span class="lab">' + CALLOUT_LABELS[k] + '</span>' + v + '</div>')
    .replace(/^### (.+)$/gm, '<h3>$1</h3>')
    .replace(/^## (\d+\. .+)$/gm, '<h2>$1</h2>')
    .replace(/^## (.+)$/gm, '<h2>$1</h2>')
    .replace(/^# (.+)$/gm, '<h1>$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/^- (.+)$/gm, '<li>$1</li>')
    .replace(/(<li>.*<\/li>\n?)+/g, '<ul>$&</ul>')
    .replace(/\n\n/g, '</p><p>')
    // A heading, a table, a list or a callout is not wrapped in a paragraph: the wrapper leaves an empty paragraph
    // behind it in the page, and print may then break between a heading and its text.
    .replace(/<p>(<(?:h[1-6]|table|div|ul)[ >])/g, '$1').replace(/(<\/(?:h[1-6]|table|div|ul)>)<\/p>/g, '$1')
    // A paragraph that is one bold line is a sub-heading. It is marked so that print keeps it with what follows.
    .replace(/<p><strong>([^<]{2,200})<\/strong>(?=<\/p>|\n<ul>)/g, '<p class="sub"><strong>$1</strong>')
    .trim();
};
const byId = {};
sources.forEach(s => { byId[s.id] = s; });
const cited = [];
(plan.match(/\b[SW]\d+\b/g) || []).forEach(id => { if (byId[id] && !cited.includes(id)) cited.push(id); });
const renderTags = (html) => html
  .replace(/\[((?:[SW]\d+)(?:\s*,\s*[SW]\d+)*)\]|\b([SW]\d+)\b/g, (m, group, bare) => (group || bare).split(/\s*,\s*/).map((id) => byId[id] ? '<sup class="tag src"><a href="#src-' + id + '">' + id + '</a></sup>' : '<sup class="tag bad">' + id + '?</sup>').join(''))
  .replace(/\[(F|A|C)\]/g, '');
const researched = data.package === 'Growth';
const legend = '<div class="legend"><strong>How to read this plan.</strong> ' + (researched ? 'Numbers like <sup class="tag src">S1</sup> point to the sources listed at the end. ' : 'No external research was done for this plan. ') + 'Anything described as an assumption has not been tested yet.</div>';
let sourcesHtml = '';
if (cited.length) {
  const accessed = byId[cited[0]].accessed || '';
  sourcesHtml = '<h2>' + ((plan.match(/^## \d+\. /gm) || []).length + 1) + '. Sources</h2><p class="srcnote">Sources were found by an automated research tool on ' + esc(accessed) + '. Each tag links a claim to the source the research tool attributed it to. Confirm any figure you rely on at the source itself.</p><ul class="sources">' + cited.map(id => {
    const s = byId[id];
    return '<li id="src-' + id + '"><strong>' + id + '.</strong> ' + esc(s.title) + '. ' + esc(s.domain) + '. Published: ' + esc(s.published) + '. Accessed: ' + esc(s.accessed) + '. ' + (s.kind === 'search_snippet' ? 'Search result listing only. ' : '') + '<a href="' + esc(s.url) + '">' + esc(s.url) + '</a></li>';
  }).join('') + '</ul>';
}
// The PDF is the customer's copy and is fingerprinted as rendered, before the owner reviews it. It carries no
// internal review status. A held version is held in the database and in the owner notice, not on the page.
const formattedContent = legend + renderTags(formatPlan(plan)) + sourcesHtml;
const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><style>body{font-family:Georgia,serif;color:#1a1a2e;margin:0;padding:0}.header{background:#1e3a5f;padding:36px 48px;border-bottom:4px solid #e8b84b}.header h1{color:#fff;margin:0;font-size:28px;letter-spacing:2px;text-transform:uppercase}.header p{color:#dbe6f2;margin:10px 0 0;font-size:15px;letter-spacing:.5px}.meta{background:#f8f4e8;padding:16px 48px;border-left:4px solid #e8b84b;font-size:13px;color:#555}.content{padding:40px 48px;max-width:800px;margin:0 auto;line-height:1.9;font-size:15px;color:#222}h2{color:#1e3a5f;font-size:20px;margin:32px 0 12px;padding-left:12px;border-left:4px solid #e8b84b}h3{color:#1e3a5f;font-size:16px;margin:24px 0 8px}table{width:100%;border-collapse:collapse;margin:16px 0}th,td{border:1px solid #d9d2c0;padding:8px 10px;font-size:14px;text-align:left;vertical-align:top}th{background:#f8f4e8;color:#1e3a5f}tr{break-inside:avoid;page-break-inside:avoid}thead{display:table-header-group}h2,h3,p.sub{break-after:avoid;page-break-after:avoid}ul{margin:12px 0 12px 24px}li{margin:6px 0;line-height:1.7}.footer{background:#1e3a5f;padding:20px 48px;text-align:center;margin-top:40px}.footer p{color:#a0b8d0;margin:0;font-size:12px}.callout{background:#f8f4e8;border:1px solid #e8b84b;border-left:6px solid #e8b84b;border-radius:4px;padding:12px 16px;margin:18px 0;line-height:1.6;page-break-inside:avoid}.callout .lab{display:block;font-family:Arial,sans-serif;font-size:11px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;color:#1e3a5f;margin-bottom:4px}.callout.risk{background:#fdf0ee;border-color:#c0564a}.callout.risk .lab{color:#9b2c1f}.legend{background:#f8f4e8;border-left:4px solid #e8b84b;padding:12px 16px;font-size:13px;line-height:1.7;margin-bottom:24px}sup.tag{font-family:Arial,sans-serif;font-size:10px;padding:0 3px;margin-left:2px;border-radius:3px;background:#eef2f7;color:#1e3a5f}sup.tag a{color:#1e3a5f;text-decoration:none}sup.tA{background:#fdf1d6;color:#7a5600}sup.bad{background:#fde2e2;color:#9b1c1c}.srcnote{font-size:13px;color:#555}ul.sources{list-style:none;margin:12px 0;padding:0}ul.sources li{font-size:12px;line-height:1.6;word-break:break-all}</style></head><body><div class="header"><h1>IDEA TO PLAN</h1><p>Business Plan - ' + (data.plan_goal_clean || 'Strategic Plan') + '</p></div><div class="meta"><strong>Prepared for:</strong> ' + properName + ' &nbsp;|&nbsp; <strong>Tier:</strong> ' + (data.package || '') + '</div><div class="content">' + formattedContent + '</div><div class="footer"><p>Built for founders ready to leap &nbsp;|&nbsp; IdeaToPlan.to</p></div></body></html>';
return [{ json: { html, client_name: properName, plan_goal_clean: data.plan_goal_clean } }];

// Citation Check: deterministic checks on the current plan, each with a severity, then builds the QA request.
// Pass 1 (first review) asks QA for a full review. Pass 2 (after a revision) asks QA only to verify the revision.
const ctx = $('Founder Context').first().json;
const fin = $('Compute Financials').first().json;
const G = ctx.tier === 'Growth';
// RUN DATE: the date this run started, read from the workflow clock. It is never hardcoded and never left to a
// model's own sense of the current year. Every prompt that judges a date is given this line.
const runDate = (() => {
  let ms = Date.now();
  try { const c = $('Founder Context').first().json; if (c && Number(c.run_started_ms) > 0) ms = Number(c.run_started_ms); } catch (e) {}
  const d = new Date(ms);
  const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const iso = d.toISOString().slice(0, 10);
  return { ms, iso, line: 'RUN DATE: today is ' + iso + ' (' + d.getUTCDate() + ' ' + MONTHS[d.getUTCMonth()] + ' ' + d.getUTCFullYear() + '), timezone UTC. This is the current date. Do not rely on your own sense of the current year. A date on or before ' + iso + ' is in the past and is not an error. Only a date after ' + iso + ' is in the future; a future publication date is an error to report and is never treated as published.' };
})();

let plan = '', attempt = 0, rev = null;
try { const r = $('Apply Revisions').first().json; if (r && typeof r.text === 'string' && r.text) { plan = r.text; attempt = 1; rev = r; } } catch (e) {}
// THE CLAIM CONTRACT IS THE DEFAULT. The final review of the whole plan is made sentence by sentence (Build Claim Review,
// Combine Claim Review). The older review, one verdict per listed line in a single response, runs only when a node
// named "Line Review" exists and returns on: true. No such node is in the workflow.
let lineReview = false;
try { lineReview = $('Line Review').first().json.on === true; } catch (e) {}
let assembly = [];
try { const asm = $('Assemble Plan').first().json; if (!plan) plan = asm.text || ''; assembly = asm.assembly_notes || []; } catch (e) {}

let sources = [], ledger = '', gaps = '', unmatched = 0, truncated = false, entitiesJson = '[]', integrity = null, excludedJson = '[]', verificationIncomplete = 0, verificationRan = false, verificationProblems = [];
if (G) {
  try { const ev = $('Build Evidence').first().json; sources = JSON.parse(ev.sources || '[]'); ledger = ev.research_ledger || ''; gaps = ev.research_gaps || ''; unmatched = ev.unmatched_markers || 0; entitiesJson = ev.entities || '[]'; try { integrity = JSON.parse(ev.source_integrity || 'null'); } catch (e2) {} excludedJson = ev.excluded_claims || '[]'; verificationIncomplete = ev.verification_incomplete || 0; verificationRan = typeof ev.verified_claims === 'number'; verificationProblems = (integrity && integrity.verification && integrity.verification.verifier_problems) || []; } catch (e) {}
  try { truncated = $('Growth Plan Generator1').first().json.choices[0].finish_reason === 'length'; } catch (e) {}
}
const known = new Set(sources.map((s) => s.id));
const issues = [];
const short = (l) => l.trim().slice(0, 200);
const add = (severity, type, detail, quote, line, extra) => issues.push({ severity, type, detail, quote: quote || '', line: line || null, ...(extra || {}) });

if (!plan) add('BLOCKING', 'NO PLAN TEXT', 'The plan text is empty.');
if (truncated) add('BLOCKING', 'TRUNCATED', 'The writer hit its token limit. The plan is incomplete.');
(fin.fin_issues || []).forEach((i) => add('BLOCKING', 'FINANCIAL MODEL', i));
(fin.fin_reviews || []).forEach((i) => add('MAJOR', 'FINANCIAL MODEL', 'A person has to review this before the plan is sent. The reviser cannot change it; it is settled at the financial-assumptions step or by the founder. ' + i));
(fin.language_flags || []).forEach((i) => add('MAJOR', 'COMPUTED CONTENT WORDING', 'Wording inside the computed financial content needs fixing at the financial-assumptions step. The reviser cannot edit computed content. ' + i));
assembly.forEach((n) => add(n.severity, 'TABLE PLACEMENT', n.detail));
if (unmatched) add('MAJOR', 'UNMATCHED MARKERS', unmatched + ' research citation markers had no matching source URL.');
ctx.section_names.forEach((s, i) => { if (!plan.includes('## ' + (i + 1) + '. ' + s)) add('BLOCKING', 'MISSING SECTION', 'Expected the header "## ' + (i + 1) + '. ' + s + '".'); });
if (fin.forecast_block && !plan.includes('They are not predictions or guarantees')) add('BLOCKING', 'MISSING FORECAST', 'The 12-month forecast and its planning-estimate statement are not in the plan.');

const calloutCount = (plan.match(/^>>/gm) || []).length;
