  const hit = sentencesOfLine(t).find((seg) => { const m = seg.match(UNKNOWN_NONE); return !!m && !/\b(?:if|whether|unless|in case)\b/i.test(seg.slice(0, m.index)) && !/\bnot (?:captured|provided|known|stated)\b/i.test(seg); });
